#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> a(N);
    int M = 0;
    for (int i = 0; i < N; i++) {
        cin >> a[i];
        M = max(M, a[i]);
    }

    int ans = 0;

    for (int h = 1; h < M; h++) {
        bool inComponent = false;
        for (int i = 0; i < N; i++) {
            if (a[i] <= h) {
                if (!inComponent) {
                    ans++;
                    inComponent = true;
                }
            } else {
                inComponent = false;
            }
        }
    }

    cout << ans << '\n';
    return 0;
}
